"""Counting mismatch: worlds vs. oracles (self-contained)."""
from __future__ import annotations
from itertools import product
from typing import List, Optional, Sequence

Truth = Sequence[int]
Oracle = Sequence[Optional[int]]

def perfect_on(oracle: Oracle, truth: Truth) -> bool:
    return all(oracle[n] is not None and oracle[n] == truth[n]
               for n in range(len(truth)))

def all_worlds(n: int) -> List[Truth]:
    return [list(bits) for bits in product((0, 1), repeat=n)]

def coverage_report(n: int, num_oracles: int) -> None:
    worlds = all_worlds(n)
    family: List[Oracle] = [list(worlds[i]) for i in range(num_oracles)]
    covered = {tuple(w) for w in worlds
               if any(perfect_on(o, w) for o in family)}
    print(f"n={n}: 2^{n}={len(worlds)} worlds, {num_oracles} oracles, "
          f"{len(covered)} covered, {len(worlds)-len(covered)} missed")
    assert len(covered) <= num_oracles

if __name__ == "__main__":
    for n in range(3, 9):
        coverage_report(n, num_oracles=10)

