function ADVERSARIAL_WORLD(O, length):
    world <- empty list
    for n in 0 .. length-1:
        a <- O(n)                       # some b, or unknown
        if a = unknown:
            append 1 to world           # any value works
        else:
            append (1 - a) to world     # opposite of O's verdict
    return world

function BLOCK_DIAGONAL_WORLD(F, length):
    world <- empty list
    for n in 0 .. length-1:
        (i, j) <- UNPAIR(n)             # Cantor pairing inverse
        if i < |F|:
            a <- F[i](n)
            append (1 if a = unknown else 1 - a) to world
        else:
            append 0 to world
    return world

function COVERED_WORLDS(F, n):
    covered <- empty set
    for each world w in {0,1}^n:
        if exists O in F with O correct on all of w:
            add w to covered
    assert |covered| <= |F|
    return |covered|

