from __future__ import annotations
from itertools import product
from typing import List, Optional, Sequence

def covered_worlds(family: Sequence[Sequence[Optional[int]]],
                   n: int) -> int:
    """Count how many of the 2^n worlds a finite oracle family is perfect for.

    Illustrates the coverage bound: the count never exceeds |family|,
    the finite/countable analogue of 'a countable family covers only
    countably many worlds'.
    """
    def perfect(o: Sequence[Optional[int]], w: Sequence[int]) -> bool:
        return all(o[k] is not None and o[k] == w[k] for k in range(n))
    covered = set()
    for bits in product((0, 1), repeat=n):
        w = list(bits)
        if any(perfect(o, w) for o in family):
            covered.add(bits)
    assert len(covered) <= len(family)
    return len(covered)
